def the_stations_and_the_death(case, data):
    """F2 — Deut 10:6-7: the stations reversed (journeys by CALL — VARIANT); Aaron died there (garments_transferred_and_aaron_died by kind — VERBATIM in kind); AND HE WAS BURIED THERE (told only here — SUPPLIED with the write buried, REUSED); the place of the death (the OPEN row — Moserah / Mount Hor, the retreat of seven stations the parameter); Eleazar ministered; Arad heard; Aaron in Av; walk after His attributes"""
