    ask = case['ask']
    if ask == 'the_stations_reversed':
        ink('10:6-7', '"and the children of Israel journeyed FROM BEEROTH-BENE-JAAKAN TO MOSERAH … from there they journeyed to GUDGODAH, and from Gudgodah to JOTBATHAH, a land of brooks of water" — the station\'s three tokens one lemma %s (the store\'s split name); Bene-jaakan\'s seats %s, Moserah/Moseroth\'s %s, Gudgodah/Hor-haggidgad\'s %s, Jotbathah\'s %s; the shared run with Numbers 33:31 %d, 33:32 %d, 33:33 %d — THE STATIONS IN ANOTHER ORDER AND ANOTHER FORM; "a land of brooks of water" %s (8:7\'s praise of the good land said of Jotbathah)' % ([lemma_of('Deut', 10, 6, t) for t in ('מבארת', 'בני', 'יעקן')], U('יעקן', 'ויעקן'), U('מוסרה', 'מסרות', 'ממסרות', 'במסרות', 'מוסרות'), U('הגדגדה', 'הגדגד'), U('יטבתה', 'ביטבתה', 'מיטבתה'), SHN(D10(6), ('Num', 33, 31)), SHN(D10(6), ('Num', 33, 32)), SHN(D10(7), ('Num', 33, 33)), P('ארץ', 'נחלי', 'מים')))
        move('cold_run_journeys (CALL) — JO.the_stations(moseroth_seven) = %s' % (JO_SEVEN[0][:90],), "Moseroth SEVEN camps before Mount Hor on the list (33:30-37: Moseroth, Bene-jaakan, Hor-haggidgad, Jotbathah, Abronah, Ezion-geber, Kadesh, Mount Hor) — Deuteronomy's Moserah after Bene-jaakan reconciled at the Numbers compile: journeys.DATA['the_deuteronomy_order'] = %s" % (JO.DATA['the_deuteronomy_order']['value'],))
        dat('the readback rows 10:6 (the stations) and 10:7 VARIANT by CALL — Moseroth then Bene-jaakan at Numbers 33:30-31, Beeroth-bene-jaakan then Moserah here (one token shared); Gudgod for Hor-haggidgad; Jotbathah\'s brooks the retelling\'s addition (Onkelos "ארע נגדא נחלין דמין" — a land flowing with streams of water); no registry row for any of the four')
